describe('task_session_highwater — casos 1 a 7 del contrato', () => {
  test('1. base nueva: la primera creación da 1 y task_highwater sigue sin existir', async () => {
    const p = nuevaBase()
    const { task_id } = await crear(p, 's1')
    expect(task_id).toBe('1')
    const db = new Database(p, { readonly: true })
    const tablas = (db.query("SELECT name FROM sqlite_master WHERE type = 'table'").all() as { name: string }[]).map((t) => t.name)
    db.close()
    expect(tablas).not.toContain('task_highwater')
    expect(tablas).toContain('task_session_highwater')
  })

  test('2. base antigua con task_highwater: la marca legada se ignora, la sesión adopta desde sus filas', async () => {
    const p = nuevaBase()
    const db = new Database(p)
    db.run(TABLERO_DDL)
    db.run(TASK_HIGHWATER_DDL)
    db.run(`INSERT INTO task_highwater (clave, max_id) VALUES ('__global__', 999)`)
    siembra(db, 's2', 3)
    const antesInfo = db.query('PRAGMA table_info(task_highwater)').all()
    const antesSql = (db.query("SELECT sql FROM sqlite_master WHERE name = 'task_highwater'").get() as { sql: string }).sql
    const antesFilas = db.query('SELECT * FROM task_highwater').all()
    db.close()

    const { task_id } = await crear(p, 's2')
    expect(task_id).toBe('4')

    const db2 = new Database(p, { readonly: true })
    const despuesInfo = db2.query('PRAGMA table_info(task_highwater)').all()
    const despuesSql = (db2.query("SELECT sql FROM sqlite_master WHERE name = 'task_highwater'").get() as { sql: string }).sql
    const despuesFilas = db2.query('SELECT * FROM task_highwater').all()
    db2.close()
    // Caso 7: la tabla legada es idéntica antes y después — el código nuevo
    // no la crea, no la lee y no la escribe.
    expect(despuesInfo).toEqual(antesInfo)
    expect(despuesSql).toEqual(antesSql)
    expect(despuesFilas).toEqual(antesFilas)
  })

  test('3. dos sesiones mantienen marcas independientes: A con 1..5 da 6, B con 1..40 da 41; crear en A no mueve B', async () => {
    const p = nuevaBase()
    const db = new Database(p)
    db.run(TABLERO_DDL)
    db.run(TASK_SESSION_HIGHWATER_DDL)
    siembra(db, 'a', 5)
    siembra(db, 'b', 40)
    db.close()

    const dadoA = await crear(p, 'a')
    expect(dadoA.task_id).toBe('6')

    const marcaB = new Database(p, { readonly: true })
      .query('SELECT next_task_id AS n FROM task_session_highwater WHERE session_id = ?')
      .get('b') as { n: number } | undefined
    expect(marcaB).toBeUndefined() // B nunca creó por la herramienta: no adoptó marca todavía.

    const dadoB = await crear(p, 'b')
    expect(dadoB.task_id).toBe('41')

    const marcaADespues = new Database(p, { readonly: true })
      .query('SELECT next_task_id AS n FROM task_session_highwater WHERE session_id = ?')
      .get('a') as { n: number }
    expect(marcaADespues.n).toBe(7) // sin moverse por la creación de B.
  })

  test('4. reinicio: cerrar y reabrir la base conserva la marca, y un id borrado no se reasigna', async () => {
    const p = nuevaBase()
    for (let i = 0; i < 5; i++) await crear(p, 'a', `tarea-${i + 1}`)
    // Las cinco creaciones dejan next_task_id en 6.
    const actualizar = taskTools({ dbPath: p, sessionId: 'a' }).find((t) => t.name === 'TaskUpdate')!
    await actualizar.run({ task_id: '5', status: 'deleted' }, ctx('a'))
    // Reabrir: un `Database` nuevo sobre el mismo archivo, como tras un reinicio.
    const marca = new Database(p, { readonly: true })
      .query('SELECT next_task_id AS n FROM task_session_highwater WHERE session_id = ?')
      .get('a') as { n: number }
    expect(marca.n).toBe(6) // borrar no bajó la marca.
    const { task_id } = await crear(p, 'a', 'otra')
    expect(task_id).toBe('6')
    expect(task_id).not.toBe('5')
  })

  test('5. concurrencia: dos sesiones a la vez no colisionan, y dentro de una da ids distintos y consecutivos', async () => {
    const p = nuevaBase()
    const resultados = await loteConcurrente(p, [
      ...Array.from({ length: 4 }, () => ({ sessionId: 'p', count: 5 })),
      ...Array.from({ length: 4 }, () => ({ sessionId: 'q', count: 5 })),
    ])
    for (const sessionId of ['p', 'q']) {
      const salidas = resultados.filter((r) => r.sessionId === sessionId).flatMap((r) => r.salidas)
      expect(salidas).toHaveLength(20)
      expect(salidas.every((s) => s.ok)).toBe(true)
      const ids = salidas.map((s) => Number(s.task_id)).sort((a, b) => a - b)
      expect(ids).toEqual(Array.from({ length: 20 }, (_, i) => i + 1))
    }
  })

  test('6. idempotencia: crear el DDL dos y tres veces no cambia filas ni esquema', async () => {
    const p = nuevaBase()
    await crear(p, 's6')
    const snapshot = () => {
      const db = new Database(p, { readonly: true })
      const info = db.query('PRAGMA table_info(task_session_highwater)').all()
      const filas = db.query('SELECT * FROM task_session_highwater ORDER BY session_id').all()
      db.close()
      return { info, filas }
    }
    const antes = snapshot()
    const db = new Database(p)
    db.run(TASK_SESSION_HIGHWATER_DDL)
    db.run(TASK_SESSION_HIGHWATER_DDL)
    db.close()
    expect(snapshot()).toEqual(antes)
  })
})
